import { create } from "zustand";
import { persist, type PersistStorage, type StorageValue } from "zustand/middleware";

import { nanoid } from "nanoid";
import { localForageStorage } from "@/lib/localforage-storage";
import { LEGACY_CANVAS_STORE_KEY, currentUserStorageScope, markLegacyLocalDataMigrated, scopedCanvasStoreKey, setCurrentUserStorageScope, shouldMigrateLegacyLocalData } from "@/services/user-scoped-storage";
import type { WorkspaceScope } from "@/stores/use-workspace-scope-store";
import type { LocalUser } from "@/stores/use-user-store";
import type { CanvasBackgroundMode } from "@/lib/canvas-theme";
import type { CanvasAssistantSession, CanvasConnection, CanvasGroupData, CanvasNodeData, ViewportTransform } from "../types";

export type CanvasProject = {
    id: string;
    title: string;
    createdAt: string;
    updatedAt: string;
    nodes: CanvasNodeData[];
    connections: CanvasConnection[];
    groups: CanvasGroupData[];
    chatSessions: CanvasAssistantSession[];
    activeChatId: string | null;
    backgroundMode: CanvasBackgroundMode;
    showImageInfo: boolean;
    viewport: ViewportTransform;
    serverProjectId?: string;
    workspaceId?: string;
    scope?: WorkspaceScope;
    snapshotVersion?: number;
    lastSyncAt?: string;
    syncStatus?: "synced" | "pending" | "conflict";
};

export type CanvasProjectSyncMeta = Pick<CanvasProject, "serverProjectId" | "workspaceId" | "snapshotVersion" | "lastSyncAt" | "syncStatus">;

type CanvasProjectPatch = Partial<Omit<CanvasProject, "id" | "createdAt">>;

type CanvasStore = {
    hydrated: boolean;
    projects: CanvasProject[];
    createProject: (title?: string, scope?: WorkspaceScope) => string;
    importProject: (project: Partial<CanvasProject>) => string;
    openProject: (id: string) => CanvasProject | null;
    upsertProject: (project: CanvasProject) => void;
    renameProject: (id: string, title: string) => void;
    deleteProjects: (ids: string[]) => void;
    replaceProjects: (projects: CanvasProject[]) => void;
    switchUserScope: (user: LocalUser | null) => Promise<void>;
    updateProject: (id: string, patch: CanvasProjectPatch) => void;
    updateProjectSyncMeta: (id: string, meta: Partial<CanvasProjectSyncMeta>) => void;
    markProjectPending: (id: string) => void;
};

const initialViewport: ViewportTransform = { x: 0, y: 0, k: 1 };
type PersistedCanvasState = Pick<CanvasStore, "projects">;
let saveTimer: ReturnType<typeof setTimeout> | null = null;
let queuedPersistState: PersistedCanvasState | null = null;
let queuedPersistValue: StorageValue<CanvasStore> | null = null;
let queuedPersistName = "";

const canvasStorage: PersistStorage<CanvasStore> = {
    getItem: async (name) => {
        const value = await localForageStorage.getItem(name);
        if (!value) return null;
        const parsed = JSON.parse(value) as StorageValue<CanvasStore>;
        queuedPersistState = parsed.state as PersistedCanvasState;
        return parsed;
    },
    setItem: (name, value) => {
        const nextState = value.state as PersistedCanvasState;
        if (queuedPersistState && queuedPersistState.projects === nextState.projects) return;
        queuedPersistState = nextState;
        queuedPersistValue = value;
        queuedPersistName = name;
        if (saveTimer) clearTimeout(saveTimer);
        saveTimer = setTimeout(() => {
            saveTimer = null;
            queuedPersistValue = null;
            queuedPersistName = "";
            void localForageStorage.setItem(name, JSON.stringify(value));
        }, 400);
    },
    removeItem: (name) => localForageStorage.removeItem(name),
};

export const useCanvasStore = create<CanvasStore>()(
    persist(
        (set, get) => ({
            hydrated: false,
            projects: [],
            createProject: (title = "未命名画布", scope = "personal") => {
                const now = new Date().toISOString();
                const id = nanoid();
                const project: CanvasProject = {
                    id,
                    title,
                    createdAt: now,
                    updatedAt: now,
                    nodes: [],
                    connections: [],
                    groups: [],
                    chatSessions: [],
                    activeChatId: null,
                    backgroundMode: "lines",
                    showImageInfo: false,
                    viewport: initialViewport,
                    scope,
                };
                set((state) => ({ projects: [project, ...state.projects] }));
                return id;
            },
            importProject: (source) => {
                const now = new Date().toISOString();
                const project: CanvasProject = {
                    id: nanoid(),
                    title: source.title || "导入画布",
                    createdAt: source.createdAt || now,
                    updatedAt: now,
                    nodes: source.nodes || [],
                    connections: source.connections || [],
                    groups: source.groups || [],
                    chatSessions: source.chatSessions || [],
                    activeChatId: source.activeChatId || null,
                    backgroundMode: source.backgroundMode || "lines",
                    showImageInfo: source.showImageInfo || false,
                    viewport: source.viewport || initialViewport,
                };
                set((state) => ({ projects: [project, ...state.projects] }));
                return project.id;
            },
            openProject: (id) => {
                const project = get().projects.find((item) => item.id === id);
                return project ? { ...project, groups: project.groups || [] } : null;
            },
            upsertProject: (project) =>
                set((state) => {
                    const exists = state.projects.some((item) => item.id === project.id);
                    return {
                        projects: exists ? state.projects.map((item) => (item.id === project.id ? project : item)) : [project, ...state.projects],
                    };
                }),
            renameProject: (id, title) =>
                set((state) => ({
                    projects: state.projects.map((project) => (project.id === id ? { ...project, title: title.trim() || project.title, updatedAt: new Date().toISOString(), syncStatus: project.serverProjectId ? "pending" : project.syncStatus } : project)),
                })),
            deleteProjects: (ids) =>
                set((state) => {
                    const projects = state.projects.filter((project) => !ids.includes(project.id));
                    return { projects };
                }),
            replaceProjects: (projects) => set({ projects }),
            switchUserScope: async (user) => {
                const nextKey = scopedCanvasStoreKey(user?.id);
                if (useCanvasStore.persist.getOptions().name === nextKey && get().hydrated) return;
                await flushPendingCanvasPersist();
                queuedPersistState = null;
                setCurrentUserStorageScope(user?.id);
                useCanvasStore.persist.setOptions({ name: scopedCanvasStoreKey(currentUserStorageScope()) });
                set({ hydrated: false, projects: [] });
                await migrateLegacyCanvasStoreForAdmin(user);
                await useCanvasStore.persist.rehydrate();
            },
            updateProject: (id, patch) =>
                set((state) => ({
                    projects: state.projects.map((project) =>
                        project.id === id
                            ? {
                                  ...project,
                                  ...patch,
                                  updatedAt: new Date().toISOString(),
                                  syncStatus: patch.syncStatus ?? (project.serverProjectId ? "pending" : project.syncStatus),
                              }
                            : project,
                    ),
                })),
            updateProjectSyncMeta: (id, meta) =>
                set((state) => ({
                    projects: state.projects.map((project) => (project.id === id ? { ...project, ...meta } : project)),
                })),
            markProjectPending: (id) =>
                set((state) => ({
                    projects: state.projects.map((project) => (project.id === id && project.serverProjectId ? { ...project, syncStatus: "pending" } : project)),
                })),
        }),
        {
            name: scopedCanvasStoreKey(),
            storage: canvasStorage,
            partialize: (state) =>
                ({
                    projects: state.projects,
                }) as StorageValue<CanvasStore>["state"],
            onRehydrateStorage: () => () => {
                useCanvasStore.setState({ hydrated: true });
            },
        },
    ),
);

async function flushPendingCanvasPersist() {
    if (!saveTimer || !queuedPersistValue || !queuedPersistName) return;
    clearTimeout(saveTimer);
    saveTimer = null;
    const value = queuedPersistValue;
    const name = queuedPersistName;
    queuedPersistValue = null;
    queuedPersistName = "";
    await localForageStorage.setItem(name, JSON.stringify(value));
}

async function migrateLegacyCanvasStoreForAdmin(user: LocalUser | null) {
    if (!shouldMigrateLegacyLocalData(user, "canvas")) return;
    const [legacyValue, scopedValue] = await Promise.all([localForageStorage.getItem(LEGACY_CANVAS_STORE_KEY), localForageStorage.getItem(scopedCanvasStoreKey(user!.id))]);
    if (legacyValue && !scopedValue) {
        await localForageStorage.setItem(scopedCanvasStoreKey(user!.id), legacyValue);
    }
    markLegacyLocalDataMigrated(user!.id, "canvas");
}
